INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'parcel', 'n.', '/ˈpɑːsl/', '包裹;邮包', 'The volunteer was so happy to get a parcel from home.', '那位志愿者收到家里寄来的包裹时非常高兴。', 'Sharing', 1, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a parcel from home', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mail', 'n./v.', '/meɪl/', '邮件;信件;邮寄', 'It is always nice to get mail when you live far away.', '住在很远的地方时,收到信件总是令人开心。', 'Sharing', 2, 0, 'senior', 'wordlist', 'elective4', 'U4', 'get the mail', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'secondary', 'adj.', '/ˈsekəndri/', '中学的;次要的', 'She teaches science at a secondary school in a poor village.', '她在一个贫困村庄的中学教科学。', 'Sharing', 3, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a secondary school', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cotton', 'n.', '/ˈkɒtn/', '棉布;棉花', 'The local boys do not even have cotton uniforms to wear.', '当地的男孩们甚至没有棉布校服可穿。', 'Sharing', 4, 0, 'senior', 'wordlist', 'elective4', 'U4', 'cotton uniforms', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'uniform', 'n./adj.', '/ˈjuːnɪfɔːm/', '校服;制服;一致的', 'Most students here cannot afford to wear a uniform.', '这里大多数学生买不起校服。', 'Sharing', 5, 0, 'senior', 'wordlist', 'elective4', 'U4', 'wear a uniform', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tablet', 'n.', '/ˈtæblət/', '平板电脑;药片;便笺本', 'The children have no laptops or tablets, only pencils and paper.', '孩子们没有笔记本电脑或平板电脑,只有铅笔和纸。', 'Sharing', 6, 0, 'senior', 'wordlist', 'elective4', 'U4', 'laptops and tablets', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rubber', 'n.', '/ˈrʌbə(r)/', '橡皮;橡胶', 'All the students had were pencils, rubbers and paper.', '学生们拥有的只有铅笔、橡皮和纸。', 'Sharing', 7, 0, 'senior', 'wordlist', 'elective4', 'U4', 'pencils and rubbers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rigid', 'adj.', '/ˈrɪdʒɪd/', '死板的;固执的;严格的', 'It is important not to be too rigid about the rules when you volunteer.', '做志愿者时,对规则不要太死板,这一点很重要。', 'Sharing', 8, 0, 'senior', 'wordlist', 'elective4', 'U4', 'be rigid about rules', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'privilege', 'n.', '/ˈprɪvəlɪdʒ/', '荣幸;优惠待遇;特权', 'She felt it was a privilege to spend a day with the family.', '她觉得能与这家人共度一天是一种荣幸。', 'Sharing', 9, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a privilege to help', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'housing', 'n.', '/ˈhaʊzɪŋ/', '住房;住宅', 'The charity helps to build simple housing for poor families.', '这家慈善机构帮助为贫困家庭建造简易住房。', 'Sharing', 10, 0, 'senior', 'wordlist', 'elective4', 'U4', 'build housing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'leftover', 'n./adj.', '/ˈleftəʊvə(r)/', '剩饭剩菜;剩余的', 'Instead of wasting the leftovers, they shared them with neighbours.', '他们没有浪费剩饭剩菜,而是分给了邻居。', 'Sharing', 11, 0, 'senior', 'wordlist', 'elective4', 'U4', 'share the leftovers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'handshake', 'n.', '/ˈhændʃeɪk/', '握手', 'We left the village after many goodbyes and firm handshakes.', '在多次道别和有力的握手之后,我们离开了村庄。', 'Sharing', 12, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a firm handshake', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'drag', 'v.', '/dræɡ/', '拖;拽;缓慢费力地移动', 'Tired but happy, we dragged ourselves down the mountain towards home.', '我们又累又开心,拖着身子下山往家走。', 'Sharing', 13, 0, 'senior', 'wordlist', 'elective4', 'U4', 'drag oneself', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'consultation', 'n.', '/ˌkɒnslˈteɪʃn/', '咨询;咨询会;会诊', 'Her mother provides consultation and training for local doctors in Africa.', '她母亲在非洲为当地医生提供咨询和培训。', 'Sharing', 14, 0, 'senior', 'wordlist', 'elective4', 'U4', 'provide consultation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'contract', 'v./n.', '/kənˈtrækt/', '感染(疾病);订立合同;合同', 'Many dangerous diseases are commonly contracted in that poor region.', '许多危险的疾病在那个贫困地区很常见。', 'Sharing', 15, 0, 'senior', 'wordlist', 'elective4', 'U4', 'contract a disease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'disability', 'n.', '/ˌdɪsəˈbɪləti/', '残疾;缺陷;障碍', 'The volunteers help those with disabilities to live a fuller life.', '志愿者们帮助残障人士过上更充实的生活。', 'Sharing', 16, 0, 'senior', 'wordlist', 'elective4', 'U4', 'people with disabilities', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'disabled', 'adj.', '/dɪsˈeɪbld/', '有残疾的;丧失能力的', 'After she retires, she hopes to continue to help the disabled.', '退休后,她希望继续帮助残障人士。', 'Sharing', 17, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the disabled', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'deserve', 'v.', '/dɪˈzɜːv/', '值得;应得;应受', 'She believes that everyone deserves a fair chance in life.', '她相信每个人在生活中都应得到一个公平的机会。', 'Sharing', 18, 0, 'senior', 'wordlist', 'elective4', 'U4', 'deserve a chance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'resign', 'v.', '/rɪˈzaɪn/', '辞职;辞去', 'He plans to resign from his job and work as a volunteer abroad.', '他打算辞职,到国外做志愿者。', 'Sharing', 19, 0, 'senior', 'wordlist', 'elective4', 'U4', 'resign from a job', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'relay', 'v./n.', '/ˈriːleɪ/', '转达;转播;接力赛', 'Today I want to relay to you how proud I am of my mother''s work.', '今天我想向你们转达我为母亲的工作感到多么自豪。', 'Sharing', 20, 0, 'senior', 'wordlist', 'elective4', 'U4', 'relay to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'stability', 'n.', '/stəˈbɪləti/', '稳定;稳固', 'Helping other countries shows that we care about world stability.', '帮助其他国家表明我们关心世界的稳定。', 'Sharing', 21, 0, 'senior', 'wordlist', 'elective4', 'U4', 'world stability', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'criterion', 'n.', '/kraɪˈtɪəriən/', '标准;准则', 'By any criterion, this kind of volunteer work is worth doing.', '无论以何种标准衡量,这种志愿工作都值得去做。', 'Sharing', 22, 0, 'senior', 'wordlist', 'elective4', 'U4', 'by any criterion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'input', 'n./v.', '/ˈɪnpʊt/', '意见;投入;输入', 'She was upset that her mother left without asking for her input.', '她很难过,母亲没有征求她的意见就离开了。', 'Sharing', 23, 0, 'senior', 'wordlist', 'elective4', 'U4', 'ask for input', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tune', 'n./v.', '/tjuːn/', '曲调;态度看法;调音', 'After hearing about her work, I began to sing a different tune.', '听说了她的工作之后,我开始改变了看法。', 'Sharing', 24, 0, 'senior', 'wordlist', 'elective4', 'U4', 'sing a different tune', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'platform', 'n.', '/ˈplætfɔːm/', '平台;站台;舞台', 'An online platform lets people share things they no longer need.', '一个在线平台让人们分享自己不再需要的物品。', 'Sharing', 25, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a sharing platform', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'lately', 'adv.', '/ˈleɪtli/', '最近;近来', 'Lately, more young people have joined volunteer projects.', '最近,越来越多的年轻人加入了志愿项目。', 'Sharing', 26, 0, 'senior', 'wordlist', 'elective4', 'U4', 'lately', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pray', 'v.', '/preɪ/', '企盼;祈祷', 'I pray that you will help people in need, just as I have.', '我企盼你也能像我一样帮助有需要的人。', 'Sharing', 27, 0, 'senior', 'wordlist', 'elective4', 'U4', 'pray that', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'grant', 'v./n.', '/ɡrɑːnt/', '同意;准许;拨款', 'We often take for granted things that poorer people lack.', '我们常常把较贫困者所缺乏的东西视为理所当然。', 'Sharing', 28, 0, 'senior', 'wordlist', 'elective4', 'U4', 'take for granted', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'shade', 'n./v.', '/ʃeɪd/', '阴凉处;遮挡(光线)', 'We walked down a shaded path to the village in the valley.', '我们沿着一条树荫遮蔽的小路走到谷中的村庄。', 'Sharing', 29, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a shaded path', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'weed', 'n./v.', '/wiːd/', '杂草;除杂草', 'The dusty track to the school was covered in weeds.', '通往学校那条尘土飞扬的小路上长满了杂草。', 'Sharing', 30, 0, 'senior', 'wordlist', 'elective4', 'U4', 'covered in weeds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dusty', 'adj.', '/ˈdʌsti/', '布满灰尘的', 'Every morning she walks to school along a dusty track.', '每天早上她沿着一条尘土飞扬的小路走去学校。', 'Sharing', 31, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a dusty track', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'hut', 'n.', '/hʌt/', '简陋的小屋;棚舍', 'The student''s family lived in a small bamboo hut with no windows.', '这名学生的家住在一间没有窗户的小竹棚里。', 'Sharing', 32, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a bamboo hut', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fireplace', 'n.', '/ˈfaɪəpleɪs/', '壁炉', 'There was a fireplace in the centre of the small hut.', '小屋的中央有一个壁炉。', 'Sharing', 33, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a fireplace in the centre', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'kettle', 'n.', '/ˈketl/', '(烧水用的)壶;水壶', 'The family''s only possessions were a kettle, some cups and a few jars.', '这家人仅有的财物是一个水壶、几个杯子和几个罐子。', 'Sharing', 34, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a kettle of water', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'jar', 'n.', '/dʒɑː(r)/', '罐子;坛子', 'Inside the parcel there was a jar of sweet jam from home.', '包裹里有一罐家里寄来的甜果酱。', 'Sharing', 35, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a jar of jam', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'jam', 'n.', '/dʒæm/', '果酱;堵塞', 'It was so nice to taste some sweets and jam from home again.', '再次尝到家里寄来的糖果和果酱真是太好了。', 'Sharing', 36, 0, 'senior', 'wordlist', 'elective4', 'U4', 'sweets and jam', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'saucer', 'n.', '/ˈsɔːsə(r)/', '茶碟;杯托', 'She placed each cup carefully on its saucer for the guests.', '她小心地把每个杯子放在杯托上招待客人。', 'Sharing', 37, 0, 'senior', 'wordlist', 'elective4', 'U4', 'cups and saucers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'forehead', 'n.', '/ˈfɔːhed/', '额头;前额', 'The old farmer had a strong jaw and a wrinkled forehead.', '那位老农有着坚毅的下巴和满是皱纹的额头。', 'Sharing', 38, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a wrinkled forehead', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'jaw', 'n.', '/dʒɔː/', '颌;下巴', 'The man with a strong jaw kindly led us to his house.', '那个下巴坚毅的男人热心地把我们带到他家。', 'Sharing', 39, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a strong jaw', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'wrinkle', 'n./v.', '/ˈrɪŋkl/', '皱纹;起皱纹', 'Years of hard work had left deep wrinkles on her face.', '多年的辛勤劳作在她脸上留下了深深的皱纹。', 'Sharing', 40, 0, 'senior', 'wordlist', 'elective4', 'U4', 'deep wrinkles', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'doorway', 'n.', '/ˈdɔːweɪ/', '门口;出入口', 'Tombe threw the empty can out of the doorway of the hut.', '通贝把空罐子从小屋的门口扔了出去。', 'Sharing', 41, 0, 'senior', 'wordlist', 'elective4', 'U4', 'in the doorway', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pan', 'n.', '/pæn/', '平底锅;烤盘', 'They cooked the sweet potatoes in a single old pan.', '他们用一个旧平底锅煮红薯。', 'Sharing', 42, 0, 'senior', 'wordlist', 'elective4', 'U4', 'pots and pans', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'ripe', 'adj.', '/raɪp/', '成熟的;时机成熟的', 'He placed ripe corn and greens on the hot stones to steam.', '他把成熟的玉米和青菜放在热石上蒸。', 'Sharing', 43, 0, 'senior', 'wordlist', 'elective4', 'U4', 'ripe corn', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tube', 'n.', '/tjuːb/', '管子;试管;管状物', 'The mixture suddenly bubbled out of the test tube during the experiment.', '实验中混合物突然从试管里冒了出来。', 'Sharing', 44, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a test tube', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'washroom', 'n.', '/ˈwɒʃruːm/', '洗手间;厕所', 'Since there was no washroom, she had to carry water from her house.', '由于没有洗手间,她不得不从家里提水。', 'Sharing', 45, 0, 'senior', 'wordlist', 'elective4', 'U4', 'no washroom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'clay', 'n.', '/kleɪ/', '黏土;陶土', 'The bush classrooms have clay floors and roofs made of grass.', '丛林里的教室有黏土地面和茅草屋顶。', 'Sharing', 46, 0, 'senior', 'wordlist', 'elective4', 'U4', 'clay floors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'plug', 'v./n.', '/plʌɡ/', '封堵;补足;插头', 'The volunteer once had to plug holes in her roof to keep the rain out.', '那位志愿者曾不得不堵住屋顶的洞以挡雨。', 'Sharing', 47, 0, 'senior', 'wordlist', 'elective4', 'U4', 'plug a hole', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'grill', 'n./v.', '/ɡrɪl/', '烤架;烤(食物)', 'She noticed a can standing upside down on the grill over the fire.', '她注意到火上的烤架上倒立着一个罐子。', 'Sharing', 48, 0, 'senior', 'wordlist', 'elective4', 'U4', 'on the grill', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u4.01', '①动词短语 / 短语动词(选正确的小品词:up/on/away/in/out/forward to 等)', 'A2', 12, '选择性必修四 U4 — take up / carry on / give away / look forward to / set up / come up with / take part in 等短语动词;空格处选构成该短语的正确小品词(adverb/particle),干扰项是同一动词配错误小品词。', 1, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u4.02', '②介词搭配(be devoted to / be grateful for / in need of / on behalf of 等)', 'A2', 12, '选择性必修四 U4 — 形容词、名词、动词与固定介词的搭配;空格处只填一个正确介词,干扰项为同结构里错误的介词。', 2, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u4.03', '③固定搭配与习语(make a difference / lend a hand / can''t help doing 等)', 'A2', 12, '选择性必修四 U4 — 整体意义固定的搭配与习语;空格处填使该习语成立的唯一正确词,干扰项为意义相近但搭配不地道的词。', 3, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'After graduation, she decided to take ____ volunteer work in a poor village.', 'up', 'off', 'in', 'over', 'A', 'take up sth = 开始从事;take up volunteer work 开始做志愿工作。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'Even when funds were low, the charity carried ____ with its work in the bush.', 'up', 'on', 'off', 'away', 'B', 'carry on = 继续(进行);其他小品词不与 carry 构成''继续''之意。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'He gave ____ most of his old clothes to families in need.', 'up', 'in', 'away', 'off', 'C', 'give away = 捐赠/赠送出去;give up 是放弃,不合句意。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The students look ____ to meeting the children at the hospital each year.', 'back', 'down', 'after', 'forward', 'D', 'look forward to = 期待;固定搭配,后接动名词。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'A group of young people set ____ a charity to help the Roma in Budapest.', 'up', 'off', 'in', 'out', 'A', 'set up = 创办/建立(一个组织)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The volunteers came ____ with a clever plan to collect food for the poor.', 'on', 'up', 'off', 'across', 'B', 'come up with = 想出(主意/计划)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'Every year his whole school takes ____ in a project to help the elderly.', 'place', 'care', 'part', 'turns', 'C', 'take part in = 参加;take part in a project 参加一个项目。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'When her mother left for Africa, she found it hard to put ____ with the loneliness.', 'off', 'on', 'away', 'up', 'D', 'put up with = 忍受;其余小品词不构成''忍受''之意。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The team handed ____ warm blankets to people at the refugee centre.', 'out', 'in', 'up', 'off', 'A', 'hand out = 分发;hand in 是上交,不合句意。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'Please do not throw ____ the leftover food; we can share it with others.', 'up', 'away', 'on', 'in', 'B', 'throw away = 扔掉;throw away the leftovers 扔掉剩饭。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The young doctor signed ____ for a one-year medical mission overseas.', 'off', 'in', 'up', 'out', 'C', 'sign up = 报名参加;sign up for a mission 报名参加任务。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'We need more hands to help ____ at the animal shelter on Sundays.', 'in', 'up', 'off', 'out', 'D', 'help out = 帮忙;help out at a shelter 在收容所帮忙。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The charity is calling ____ young people to give some of their free time.', 'on', 'off', 'up', 'in', 'A', 'call on sb to do = 号召/呼吁某人做某事。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'After hearing her mother''s story, she came ____ to support the work fully.', 'off', 'round', 'up', 'in', 'B', 'come round = (改变想法后)转而支持/被说服。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'Volunteers must adapt ____ the simple conditions in the remote village.', 'for', 'with', 'to', 'at', 'C', 'adapt to = 适应;adapt to the conditions 适应这些条件。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The school carried ____ a campaign to collect books for poor children.', 'on', 'up', 'in', 'out', 'D', 'carry out = 实施/开展(活动/计划)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'She handed ____ her project report before joining the volunteer trip.', 'in', 'out', 'up', 'off', 'A', 'hand in = 上交;此处指交报告,与 hand out(分发)相对。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The volunteers set ____ early in the morning to reach the mountain village.', 'up', 'off', 'in', 'down', 'B', 'set off = 出发/动身;set off early 早早出发。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'Don''t give ____ even when the volunteer work feels really hard at first.', 'away', 'off', 'up', 'in', 'C', 'give up = 放弃;此处指不要放弃,与 give away(捐出)区分。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.01'), 'The students take ____ donations of clothes and toys for the refugee centre.', 'off', 'up', 'away', 'in', 'D', 'take in = 收下/接收;take in donations 接收捐赠物。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'Her mother is devoted ____ helping people in distant African villages.', 'to', 'for', 'with', 'on', 'A', 'be devoted to = 致力于/献身于;to 后接动名词。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The poor families were grateful ____ every parcel the volunteers brought.', 'to', 'for', 'of', 'with', 'B', 'be grateful for sth = 因某事而感激。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The hospital was badly in need ____ doctors who could speak the local language.', 'for', 'to', 'of', 'with', 'C', 'in need of = 需要;固定搭配用 of。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'On ____ of the whole class, Tony thanked the children''s hospital staff.', 'side', 'part', 'place', 'behalf', 'D', 'on behalf of = 代表;固定名词搭配。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The volunteers expected nothing in ____ for their hard work.', 'return', 'reply', 'exchange', 'answer', 'A', 'in return (for) = 作为回报;固定搭配。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'Many people there live without things we are used ____ having every day.', 'for', 'to', 'with', 'of', 'B', 'be used to (doing) = 习惯于;to 后接动名词。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'She was upset that her mother left without asking ____ her opinion.', 'to', 'of', 'for', 'at', 'C', 'ask for sth = 请求/征求(意见)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The young doctors are proud ____ the work they do for the needy.', 'for', 'with', 'to', 'of', 'D', 'be proud of = 为……感到自豪。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'We should feel responsible ____ those who are less fortunate than us.', 'for', 'to', 'of', 'with', 'A', 'be responsible for = 对……负责。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The medical team provided free treatment ____ patients in the rural villages.', 'to', 'for', 'with', 'of', 'B', 'provide sth for sb = 为某人提供某物(provide medical treatment for patients)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The charity is committed ____ building a better world for everyone.', 'for', 'with', 'to', 'on', 'C', 'be committed to (doing) = 致力于;to 后接动名词。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'These young people are willing to care ____ strangers in need of help.', 'to', 'of', 'with', 'for', 'D', 'care for sb = 关心/照顾某人。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'Volunteers are often faced ____ very difficult living conditions abroad.', 'with', 'for', 'to', 'of', 'A', 'be faced with = 面临/面对;固定搭配用 with。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The local people benefit greatly ____ the new cardiac hospital.', 'for', 'from', 'to', 'of', 'B', 'benefit from = 从……中受益。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'Her team contributed ____ saving many lives with a new malaria treatment.', 'for', 'with', 'to', 'of', 'C', 'contribute to (doing) = 有助于/为……作贡献;to 后接动名词。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'These volunteers are ready to share their skills ____ needy communities.', 'for', 'to', 'of', 'with', 'D', 'share sth with sb = 与某人分享某物。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'He finally became supportive ____ his mother''s work in Tanzania.', 'of', 'for', 'to', 'with', 'A', 'be supportive of = 支持(某人/某事)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'The programme depends ____ how well each volunteer performs.', 'of', 'on', 'to', 'for', 'B', 'depend on = 取决于/依赖。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'We must not take such everyday comforts ____ granted.', 'as', 'to', 'for', 'of', 'C', 'take sth for granted = 视为理所当然;固定搭配用 for。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.02'), 'She is interested ____ joining the next volunteer trip to Ghana.', 'on', 'for', 'to', 'in', 'D', 'be interested in (doing) = 对……感兴趣;in 后接动名词。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Even a small act of kindness can make a ____ to someone''s life.', 'difference', 'change', 'matter', 'sense', 'A', 'make a difference = 起作用/带来改变;固定习语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'When the team was short of helpers, several neighbours lent a ____.', 'foot', 'hand', 'finger', 'head', 'B', 'lend a hand = 帮忙;固定习语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Instead of paying her back, she chose to pay it ____ to others in need.', 'back', 'off', 'forward', 'out', 'C', 'pay it forward = 把善意传递给他人;固定说法。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Seeing the children so happy, she couldn''t help ____ with joy.', 'smile', 'to smile', 'smiled', 'smiling', 'D', 'can''t help doing = 禁不住做某事;后接动名词。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'It''s no use ____ about the problem; we should go out and help.', 'complaining', 'complain', 'to complain', 'complained', 'A', 'it''s no use doing = 做……没有用;后接动名词。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'The volunteers worked hard to make the world a ____ place to live in.', 'best', 'better', 'well', 'good', 'B', 'make … a better place = 让……变得更好;比较级 better 修饰 place。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'She felt it was worth ____ a whole day with the village family.', 'spend', 'to spend', 'spending', 'spent', 'C', 'be worth doing = 值得做;后接动名词。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'The charity always tries to give those in ____ a helping hand.', 'needs', 'needy', 'needed', 'need', 'D', 'those in need = 有需要的人;固定搭配用名词 need。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Many people went ____ medical treatment because it was too expensive.', 'without', 'out', 'off', 'away', 'A', 'go without sth = 没有……也将就过/缺少;go without treatment 得不到治疗。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Helping others, she said, comes at the ____ of her list of proud things.', 'high', 'top', 'front', 'head', 'B', 'at the top of the list = 在名单首位;固定搭配。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'The volunteers gave their time and money, asking for nothing in ____.', 'reward', 'repay', 'return', 'result', 'C', 'ask for nothing in return = 不求回报;固定习语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Thanks to the new hospital, fewer patients have to go ____ for surgery.', 'aboard', 'around', 'above', 'abroad', 'D', 'go abroad = 出国;此处指出国做手术。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'After the meal, the family talked softly and made us feel at ____.', 'home', 'house', 'ease', 'rest', 'A', 'make sb feel at home = 让某人感到自在;固定习语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'The young charity is breaking ____ in the way it helps poor communities.', 'land', 'ground', 'earth', 'floor', 'B', 'break new ground = 开创新局面/有所突破;固定习语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'When her mother returned, the family was finally ____ together again.', 'down', 'off', 'back', 'up', 'C', 'be back together = 重新团聚;back 表''回到原来状态''。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Volunteering, she realised, is a way of giving ____ to society.', 'away', 'off', 'out', 'back', 'D', 'give back (to society) = 回馈(社会);固定搭配。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'We are ready to build a community with a ____ future for mankind.', 'shared', 'share', 'sharing', 'shares', 'A', 'a shared future = 共同的未来;过去分词作定语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'No matter how small your effort is, it counts ____ a great deal.', 'on', 'for', 'to', 'in', 'B', 'count for a great deal = 很有价值/很重要;固定搭配用 for。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'The volunteers were determined to make the ____ of their short stay.', 'best', 'more', 'most', 'much', 'C', 'make the most of = 充分利用;固定习语用 most。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U4' AND code='e4u4.03'), 'Helping the disabled gave her a deep ____ of purpose in life.', 'feeling', 'idea', 'mind', 'sense', 'D', 'a sense of purpose = 使命感/目标感;固定搭配用 sense。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Teaching in the Bush', 'Jo has been a volunteer teacher in a bush school for about a month. The classrooms there are made of bamboo, with clay floors and roofs of grass. Every morning she walks to school down a dusty track covered in weeds, and the boys greet her with a cheerful chorus of "good morning". Unlike students back home, these boys do not wear cotton uniforms, and many of them walk for up to two hours just to reach the school. There is no electricity, no running water and not even any textbooks, let alone laptops or tablets. All the students have are pencils, rubbers and paper. Jo has had to become far more imaginative in her teaching, and she has learned not to be too rigid about the rules. At times she wonders whether she is really making any difference to these boys'' lives. Yet the boys clearly value the chance to learn, and that keeps her going.', 'Sharing', 157, '[{"q":"What is Jo''s job in the village?","answer":"A","options":["She works there as a volunteer teacher.","She sells uniforms to the boys.","She builds bamboo classrooms.","She repairs the school''s electricity."],"explanation":"首句说明 Jo 是丛林学校的志愿教师,其余选项文中未提或相反。"},{"q":"What do the students lack at the school?","answer":"B","options":["Friendly teachers.","Basic things such as electricity and textbooks.","A daily walk to school.","Pencils and paper."],"explanation":"文中说没有电、没有自来水、没有课本,概括为缺基本设施;最后一项相反(他们有铅笔和纸)。"},{"q":"Why does Jo keep going despite her doubts?","answer":"A","options":["Because the boys really treasure their chance of getting an education.","Because the pay is very high.","Because the school has modern devices.","Because the walk to school is short."],"explanation":"末句说男孩们珍视学习机会,这让她坚持下去。"}]'::jsonb, '[{"word":"bush","cn":"丛林;偏远的乡野"},{"word":"rigid","cn":"死板的"},{"word":"dusty","cn":"布满灰尘的"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'A Day with a Village Family', 'Last weekend Jo visited a remote village, the home of one of her students, Tombe. After walking for over two hours across a mountain and down a shaded path, she reached a low bamboo hut with no windows. Inside it was dark, and the only possessions she could see were a broom, a few saucers, a kettle and a couple of jars. Tombe''s father heated some stones on a fire and used them to steam sweet potatoes, ripe corn and greens, which smelled delicious. The whole family sat round the fire and ate together. Later Jo noticed a can being heated and then thrown out of the doorway. Tombe explained that drying out the leftover food in this way was part of their beliefs. Though the family had almost nothing, they shared everything they could with their guests. When Jo left the next morning after many warm handshakes, she felt that spending a day with them had been a real privilege.', 'Sharing', 161, '[{"q":"What was Tombe''s family home like?","answer":"B","options":["A large modern house full of furniture.","A simple dark hut with very few possessions.","A school building made of stone.","A shop selling food to visitors."],"explanation":"文中描述是没有窗户、内部昏暗、几乎没有家当的小竹棚,概括为简陋小屋。"},{"q":"How did the family treat their guest?","answer":"C","options":["They asked her to leave at once.","They charged her for the meal.","They shared what little they had with her.","They ignored her during dinner."],"explanation":"文中说一家人几乎一无所有却尽力分享,概括为''分享所有''。"},{"q":"How did Jo feel about the visit?","answer":"D","options":["She felt bored and uncomfortable.","She felt sorry that she had gone.","She felt angry about the simple food.","She felt it had been a true privilege."],"explanation":"末句说她觉得这是一种真正的荣幸。"}]'::jsonb, '[{"word":"hut","cn":"简陋的小屋"},{"word":"leftover","cn":"剩饭剩菜"},{"word":"privilege","cn":"荣幸"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Why Helping Others Far Away Is Worth It', 'Bingbing''s mother is a medical doctor who has spent two years as a volunteer in Tanzania, a country with many health problems. At first Bingbing was upset, because her mother had always cooked for her and was her best friend, and she had left without even asking for Bingbing''s opinion. But as Bingbing learned more about the work, she began to sing a different tune. In Tanzania, many people live without things that Bingbing''s family take for granted, such as electricity, running water and good hospitals. Her mother helped to build a heart hospital, so that patients no longer had to go abroad for costly surgery. She also travelled to rural villages to treat the sick, help those with disabilities and train local doctors. Some may ask whether such work is worth it. Bingbing now firmly believes it is, both for the lives it saves and because it shows that Chinese people care about a shared future for all of mankind.', 'Sharing', 161, '[{"q":"Why was Bingbing upset at first?","answer":"A","options":["Her mother had left without asking how she felt.","Her mother had stopped being a doctor.","She had to move to Tanzania too.","Her mother had never cooked for her."],"explanation":"文中说母亲没征求她的意见就离开了,所以她不高兴;最后一项与原文相反。"},{"q":"What did Bingbing''s mother do in Tanzania?","answer":"B","options":["She opened a private business.","She helped build a hospital and treated the sick.","She studied at a local school.","She trained as a heart patient."],"explanation":"文中说她帮助建心脏医院并到乡村治病、培训医生,概括为''建医院、治病''。"},{"q":"What does Bingbing think about her mother''s work now?","answer":"C","options":["She thinks it is a waste of time.","She wishes her mother would stop.","She firmly believes it is worth doing.","She is no longer interested in it."],"explanation":"末句说她现在坚信这项工作是值得的。"}]'::jsonb, '[{"word":"tune","cn":"(sing a different tune)改变看法"},{"word":"disability","cn":"残疾"},{"word":"shared","cn":"共同的"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'One Pair for One Pair', 'People''s Shoes is a company that wants to create a better world through sharing. Its idea is simple but powerful: for every pair of shoes a customer buys, the company donates a pair to someone who is in need. In this way, ordinary shoppers can help others without spending any extra money. But the company does more than give away shoes. It also provides surgery and medical treatment to people with eye problems, and it brings clean water systems to communities where the drinking water is unsafe. Today People''s Shoes works in about seventy countries around the world. The message behind it is that doing good and doing business do not have to be separate things. By choosing where to spend their money, customers can quietly make a difference to the lives of strangers far away. The company hopes that more businesses will follow this example and put kindness at the heart of what they do.', 'Sharing', 156, '[{"q":"How does People''s Shoes help people in need?","answer":"D","options":["It sells shoes at a very high price.","It only helps people in one country.","It collects old shoes from the rich.","It gives one pair of shoes for each pair sold."],"explanation":"文中说每卖出一双就捐一双,概括为''每售一双捐一双''。"},{"q":"Besides shoes, what else does the company offer?","answer":"A","options":["Eye treatment and clean water systems.","Free holidays for shoppers.","New cars for poor families.","Jobs in its head office."],"explanation":"文中提到为眼疾患者提供手术治疗,并带来干净的供水系统。"},{"q":"What is the main message of the passage?","answer":"B","options":["Shoes should always be expensive.","Helping people and running a company can work together.","Charity work is only for rich people.","Companies should never give anything away."],"explanation":"文中说做好事与做生意不必分开,这是文章主旨。"}]'::jsonb, '[{"word":"donate","cn":"捐赠"},{"word":"in need","cn":"有需要的"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'A Charity Run by Young People', 'Most is a small charity that is run entirely by young people in Budapest, the capital of Hungary. One group it tries to help is the Roma, an ethnic group in Europe that is often poor and treated unfairly. The members of Most feel that they should not only enjoy the comfortable lives they have in the city, but also share what they have with people elsewhere in the country. They believe it is a kind of duty to help those who have less than they do. The young volunteers visit poorer communities, bring donations and spend time with families who need support. They also plan to help at a refugee centre in a neighbouring country. For these young people, helping others is not a burden but something that gives their own lives more meaning. They hope that their example will encourage other youngsters to look beyond themselves and do something good for the wider world.', 'Sharing', 156, '[{"q":"Who runs the charity called Most?","answer":"C","options":["The government of Hungary.","A group of rich businessmen.","Young people in Budapest.","Teachers from a refugee centre."],"explanation":"首句说 Most 完全由布达佩斯的年轻人运营。"},{"q":"Why do the members want to help others?","answer":"D","options":["Because they are paid a lot of money.","Because the city forces them to.","Because they want to become famous.","Because they feel it is a duty to share with those who have less."],"explanation":"文中说他们觉得帮助比自己拥有更少的人是一种责任。"},{"q":"How does helping others affect these young people?","answer":"A","options":["It makes their own lives feel more meaningful.","It makes their lives very boring.","It costs them all their free time for nothing.","It makes them want to leave the country."],"explanation":"文中说帮助别人不是负担,而是让他们的生活更有意义。"}]'::jsonb, '[{"word":"charity","cn":"慈善机构"},{"word":"donation","cn":"捐赠物"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Things We Take for Granted', 'When we turn on a tap and clean water flows out, most of us never stop to think about it. We flick a switch and the lights come on; we open a fridge full of food whenever we feel hungry. These small comforts feel so normal that we take them completely for granted. Yet in many parts of the world, people live without running water, electricity or enough to eat. Spending time with such families often changes the way visitors see their own lives. They begin to notice how much they have, and how little they once valued it. This is one of the quiet gifts of volunteering: it teaches us gratitude. People who have shared a meal in a simple hut often say that the experience made them more thankful and more willing to help others. Learning to be grateful for what we have is the first step towards being generous with it.', 'Sharing', 154, '[{"q":"What everyday comforts does the writer mention?","answer":"B","options":["Cars, planes and trains.","Clean water, electricity and food.","Phones, games and films.","Schools, books and pens."],"explanation":"文中举例自来水、电和食物等日常便利。"},{"q":"What does spending time with poor families often do to visitors?","answer":"C","options":["It makes them feel proud and selfish.","It makes them forget their own lives.","It changes the way they see their own lives.","It makes them dislike helping others."],"explanation":"文中说与这样的家庭相处往往改变访客看待自己生活的方式。"},{"q":"According to the writer, what is the first step towards being generous?","answer":"D","options":["Buying more expensive things.","Travelling to many countries.","Keeping everything for ourselves.","First learning to feel thankful for all that we already own."],"explanation":"末句说学会对所拥有的心怀感恩是慷慨的第一步。"}]'::jsonb, '[{"word":"take for granted","cn":"视为理所当然"},{"word":"gratitude","cn":"感恩"}]'::jsonb, 2, 'elective4', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'A Parcel from Home', 'I have been teaching in this faraway village for about a month now, and today something wonderful happened: I got a (1)____ from home! It took two weeks to arrive and was a little (2)____, but inside there were sweets and a jar of (3)____. It is always so nice to get (4)____ when you live this far away. Life here is simple. There is no (5)____, so in the evenings I work by candlelight. The students wear no cotton (6)____ and have only pencils and paper. At first I felt very (7)____, far from my family and friends. But slowly I have learned to (8)____ to the quiet life. The boys'' bright smiles make a real (9)____ to my days. Tonight, eating my sweets, I feel grateful to be (10)____ my life with these kind people.', 137, 2, '[{"q":"1","answer":"A","options":["parcel","river","noise","fence"],"explanation":"a parcel from home 家里寄来的包裹。"},{"q":"2","answer":"B","options":["fresh","damaged","empty","loud"],"explanation":"a little damaged 有点损坏(原文称包裹略受损)。"},{"q":"3","answer":"C","options":["coal","stone","jam","smoke"],"explanation":"a jar of jam 一罐果酱。"},{"q":"4","answer":"D","options":["rain","dust","fire","mail"],"explanation":"get mail 收到信件。"},{"q":"5","answer":"A","options":["electricity","weather","language","weekend"],"explanation":"no electricity 没有电。"},{"q":"6","answer":"B","options":["songs","uniforms","prices","tickets"],"explanation":"cotton uniforms 棉布校服。"},{"q":"7","answer":"C","options":["proud","rich","lonely","lazy"],"explanation":"feel lonely 感到孤独。"},{"q":"8","answer":"D","options":["refuse","shout","drop","adapt"],"explanation":"adapt to 适应。"},{"q":"9","answer":"A","options":["difference","price","noise","machine"],"explanation":"make a difference 起作用/带来改变。"},{"q":"10","answer":"B","options":["selling","sharing","hiding","losing"],"explanation":"sharing my life with 与……分享生活。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'Xu Yuan in Ghana', 'Xu Yuan is a Chinese (1)____ working in Ghana. She says the living conditions there are not as (2)____ as people imagine. Once she even had to (3)____ holes in her roof to keep the rain out. "I don''t really (4)____ about my own comfort," she explained. "The only hard thing has been the (5)____ of hot water." She wishes she had brought a (6)____ to boil water, because some of her medicine works better with it. Still, any small discomfort is (7)____ it, she believes, when she thinks of the people she helps. Xu enjoys being pushed out of her (8)____ zone and seeing the world. After she (9)____ from her job, she hopes to continue to help the (10)____. "Everyone deserves the chance to be happy," she said.', 130, 2, '[{"q":"1","answer":"C","options":["machine","garden","volunteer","market"],"explanation":"a Chinese volunteer 一名中国志愿者。"},{"q":"2","answer":"D","options":["loud","sweet","tall","bad"],"explanation":"not as bad as 不像想象的那么糟。"},{"q":"3","answer":"A","options":["plug","sell","lose","throw"],"explanation":"plug holes 堵住洞。"},{"q":"4","answer":"B","options":["sing","care","drive","cook"],"explanation":"care about 在意/关心。"},{"q":"5","answer":"C","options":["price","song","lack","noise"],"explanation":"the lack of hot water 缺乏热水。"},{"q":"6","answer":"D","options":["ticket","garden","letter","kettle"],"explanation":"a kettle to boil water 烧水的水壶。"},{"q":"7","answer":"A","options":["worth","over","above","under"],"explanation":"be worth it 值得。"},{"q":"8","answer":"B","options":["danger","comfort","market","garden"],"explanation":"comfort zone 舒适区。"},{"q":"9","answer":"C","options":["buys","drops","resigns","sells"],"explanation":"resign from a job 辞职。"},{"q":"10","answer":"D","options":["richest","youngest","tallest","disabled"],"explanation":"help the disabled 帮助残障人士。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'A Speech about China''s Aid', 'Lately, many of us have seen Chinese people on TV (1)____ other countries to develop. We see workers building roads, ports and railways in faraway (2)____. Some people ask whether this is really (3)____ it, when China still has areas in (4)____ of development. For one student, the question was personal. Her mother, a doctor, has been working as a (5)____ in Tanzania. At first the student was (6)____ that her mother had left. But when she learned about the work, she began to (7)____ a different tune. Her mother helped to build a hospital, so patients no longer had to go (8)____ for surgery. It has made a big (9)____ to many lives. Today the student is proud and (10)____ of her mother''s choice, and she hopes to become a volunteer herself one day.', 135, 2, '[{"q":"1","answer":"A","options":["helping","leaving","selling","hiding"],"explanation":"helping other countries 帮助别国。"},{"q":"2","answer":"B","options":["machines","places","prices","noises"],"explanation":"faraway places 遥远的地方。"},{"q":"3","answer":"C","options":["wide","deep","worth","rich"],"explanation":"worth it 值得。"},{"q":"4","answer":"D","options":["price","song","rain","need"],"explanation":"in need of 需要。"},{"q":"5","answer":"A","options":["volunteer","garden","ticket","machine"],"explanation":"as a volunteer 作为志愿者。"},{"q":"6","answer":"B","options":["proud","upset","happy","calm"],"explanation":"upset 难过(原文起初不开心)。"},{"q":"7","answer":"C","options":["sell","lose","sing","throw"],"explanation":"sing a different tune 改变看法。"},{"q":"8","answer":"D","options":["away","around","above","abroad"],"explanation":"go abroad 出国(做手术)。"},{"q":"9","answer":"A","options":["difference","price","noise","garden"],"explanation":"make a difference 带来改变。"},{"q":"10","answer":"B","options":["afraid","supportive","tired","bored"],"explanation":"supportive of 支持。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'Planning a Volunteer Project', 'At today''s meeting, the students wanted to (1)____ on a volunteer project for this year. "May I (2)____ that we visit the children''s hospital?" Tony said. "We could spend (3)____ with the sick children and bring them small gifts." Another student thought they should (4)____ money for poor families instead. "Wouldn''t it be better if we did (5)____?" she asked. "We can both raise money and (6)____ a hand at the hospital." Everyone liked this idea, because it would (7)____ a real difference to more people. They also agreed to (8)____ up a small team to plan the activities. "Let''s not just talk about it," Tony said. "Let''s (9)____ it!" In the end, the class voted, and helping at the children''s hospital came at the (10)____ of the list.', 129, 2, '[{"q":"1","answer":"C","options":["sleep","drive","decide","cook"],"explanation":"decide on 决定(选定)。"},{"q":"2","answer":"D","options":["sell","lose","throw","suggest"],"explanation":"May I suggest that …? 我可以建议……吗?"},{"q":"3","answer":"A","options":["time","price","noise","rain"],"explanation":"spend time with 与……共度时光。"},{"q":"4","answer":"B","options":["lose","raise","drop","hide"],"explanation":"raise money 筹钱。"},{"q":"5","answer":"C","options":["less","worse","both","nothing"],"explanation":"did both 两件事都做。"},{"q":"6","answer":"D","options":["sell","drop","throw","lend"],"explanation":"lend a hand 帮忙。"},{"q":"7","answer":"A","options":["make","lose","sell","hide"],"explanation":"make a difference 带来改变。"},{"q":"8","answer":"B","options":["give","set","throw","fall"],"explanation":"set up a team 组建团队。"},{"q":"9","answer":"C","options":["sell","lose","do","hide"],"explanation":"let''s do it 我们去做吧。"},{"q":"10","answer":"D","options":["bottom","side","back","top"],"explanation":"at the top of the list 在首位。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'A New Way of Sharing', 'These days, sharing does not always mean (1)____ things away forever. Online (2)____ now let people share what they no longer use. If you have books, tools or toys (3)____ around your house, you can offer them to someone who is in (4)____ of them. In (5)____, you might borrow something you need from a neighbour. This idea is good for everyone and (6)____ for the planet too, because fewer things are (7)____ away. Some young people have even (8)____ up small groups to share food that would otherwise be wasted. Leftover bread and fruit are collected and (9)____ out to those who need them. In this way, a simple act of sharing can (10)____ a real difference to a whole community.', 122, 2, '[{"q":"1","answer":"A","options":["giving","buying","hiding","eating"],"explanation":"give things away 把东西送出去。"},{"q":"2","answer":"B","options":["gardens","platforms","prices","noises"],"explanation":"online platforms 在线平台。"},{"q":"3","answer":"C","options":["selling","crying","sitting","running"],"explanation":"sitting around 闲置着。"},{"q":"4","answer":"D","options":["price","song","rain","need"],"explanation":"in need of 需要。"},{"q":"5","answer":"A","options":["return","price","noise","garden"],"explanation":"in return 作为回报。"},{"q":"6","answer":"B","options":["bad","good","loud","sad"],"explanation":"good for the planet 对地球有益。"},{"q":"7","answer":"C","options":["sung","drawn","thrown","grown"],"explanation":"thrown away 被扔掉。"},{"q":"8","answer":"D","options":["given","fallen","thrown","set"],"explanation":"set up groups 组建小组。"},{"q":"9","answer":"A","options":["handed","sold","lost","hidden"],"explanation":"handed out 分发出去。"},{"q":"10","answer":"B","options":["lose","make","sell","hide"],"explanation":"make a difference 带来改变。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U4', 'Learning to Be Grateful', 'Before I joined the volunteer trip, I (1)____ so many things for granted. Clean water, warm food and a soft bed all felt (2)____ to me. But living for a week in a simple (3)____ with no electricity changed the way I (4)____ my own life. The family I stayed with had almost nothing, yet they were happy to (5)____ everything they had with me. After every meal we sat round the (6)____ and talked softly. Their kindness taught me to be (7)____ for what I have. Now I never (8)____ leftover food without thinking of them. When I came home, I decided to (9)____ a hand to others whenever I can. Helping people, I have learned, can (10)____ a difference not only to them, but also to me.', 129, 2, '[{"q":"1","answer":"C","options":["sold","lost","took","drew"],"explanation":"took … for granted 把……视为理所当然。"},{"q":"2","answer":"D","options":["loud","empty","rich","normal"],"explanation":"felt normal 感觉很平常。"},{"q":"3","answer":"A","options":["hut","shop","city","market"],"explanation":"a simple hut 简陋的小屋。"},{"q":"4","answer":"B","options":["sold","saw","lost","drew"],"explanation":"the way I saw my life 我看待生活的方式。"},{"q":"5","answer":"C","options":["sell","hide","share","lose"],"explanation":"share … with me 与我分享。"},{"q":"6","answer":"D","options":["noise","price","garden","fire"],"explanation":"sat round the fire 围坐在火边。"},{"q":"7","answer":"A","options":["grateful","angry","afraid","bored"],"explanation":"be grateful for 对……感激。"},{"q":"8","answer":"B","options":["buy","waste","grow","draw"],"explanation":"waste leftover food 浪费剩饭。"},{"q":"9","answer":"C","options":["sell","lose","lend","hide"],"explanation":"lend a hand 帮忙。"},{"q":"10","answer":"D","options":["lose","sell","hide","make"],"explanation":"make a difference 带来改变。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 The Animal Shelter Ad', '选择性必修四 U4 · dialogue', 3, 'Jessie: Susan, did you see the animal shelter advertisement? It would be great for our volunteer project.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 What Volunteering Teaches Us', '选择性必修四 U4 · passage', 2, 'Many young people think that volunteering is only about giving to others.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 Deciding What to Donate', '选择性必修四 U4 · dialogue', 3, 'Liu: Our class wants to donate something to the poor children in the countryside. What do you think we should give?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 Sharing Instead of Wasting', '选择性必修四 U4 · passage', 2, 'Every day, a huge amount of good food is thrown away in our cities.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 A Call to a Volunteer Abroad', '选择性必修四 U4 · dialogue', 3, 'Mum: Hi, dear. How is your volunteer teaching going so far?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 A Thank-You Message', '选择性必修四 U4 · passage', 2, 'On behalf of all the children here, I would like to thank our visitors.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write about a Volunteer / Charity Experience(写一次志愿或公益经历)', 'A Day I Spent Helping Others', '假设你叫李华,上个周末你和同学参加了一次志愿活动(如去敬老院/儿童医院/动物收容所,或为贫困地区捐书捐衣)。请用英语写一篇约100词的短文,内容包括:① 你们做了什么活动;② 活动中印象最深的一件事;③ 这次经历让你明白了什么(如分享/感恩/帮助他人)。注意:用上本单元的短语(如 take part in / lend a hand / make a difference)。', 'Suppose you are Li Hua. Last weekend you and your classmates took part in a volunteer activity (e.g. visiting a care home, a children''s hospital or an animal shelter, or donating books and clothes to a poor area). Write a passage of about 100 words including: 1) what you did; 2) the one thing that impressed you most; 3) what the experience taught you (e.g. about sharing, gratitude or helping others). Try to use phrases from this unit such as take part in, lend a hand and make a difference.', '["说明做了什么活动(Last weekend we took part in …)","印象最深的一件事(What impressed me most was …)","谈收获/感悟(This experience taught me that …)","用上本单元短语:take part in / lend a hand / make a difference"]'::jsonb, 70, 100, 'Last weekend, my classmates and I took part in a volunteer activity at a local children''s hospital. We brought books and small gifts, and spent the whole morning reading stories and playing games with the sick children. At first some of them were shy, but soon their faces lit up with bright smiles. What impressed me most was a little boy who thanked us again and again, although we had only lent a small hand. That moment made me realise how much even a simple act of sharing can mean to others. This experience taught me that helping people can truly make a difference — not only to them, but also to me.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Last weekend, my classmates and I took part in a volunteer activity at a local children''s hospital.","What impressed me most was a little boy who thanked us again and again.","Even a simple act of sharing can mean a lot to others.","This experience taught me that helping people can truly make a difference."]'::jsonb, '[{"wrong":"We took part in a volunteer activity in last weekend.","correct":"We took part in a volunteer activity last weekend.","note":"last weekend 前不加介词 in。"},{"wrong":"What impressed me most were a little boy.","correct":"What impressed me most was a little boy.","note":"what 引导的主语从句视为单数,谓语用 was。"},{"wrong":"It can make a different to others.","correct":"It can make a difference to others.","note":"固定搭配是 make a difference(名词),不是 different(形容词)。"}]'::jsonb, '【志愿/公益经历结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective4', 'U4', '{"title":"短语复习速查:动词短语 · 介词搭配 · 固定习语","intro":"短语是英语的''血肉''。三大类要分清:① 动词短语/短语动词(动词+小品词,意义常引申,如 give away ≠ give);② 介词搭配(形容词/名词/动词后跟固定介词,如 be devoted to);③ 固定搭配与习语(整体意义固定,如 make a difference)。判断口诀:记搭配、辨小品词、抠介词。","table":{"headers":["类别","例子 / 含义"],"rows":[["动词短语","take up 开始从事 · carry on 继续 · give away 捐出 · set up 创办 · come up with 想出"],["短语动词(可分)","hand out 分发 · hand in 上交 · give up 放弃 · throw away 扔掉"],["介词搭配","be devoted to 致力于 · be grateful for 感激 · in need of 需要 · on behalf of 代表"],["固定习语","make a difference 起作用 · lend a hand 帮忙 · take … for granted 视为理所当然 · in return 作为回报"]]},"specialRules":[{"rule":"同一动词配不同小品词,意义大不同:give up(放弃)/ give away(捐出)/ give back(回馈)","mark":"看句意选小品词"},{"rule":"be devoted/committed/used to 中的 to 是介词,后接动名词(doing),不是动词原形","mark":"be devoted to helping √"},{"rule":"固定习语整体记忆,不可随意换词:make a difference(不可 make a different)","mark":"difference 是名词"},{"rule":"can''t help doing / it''s no use doing / be worth doing 后一律用动名词","mark":"couldn''t help smiling √"}],"why":["短语动词里的小品词(up/away/out…)往往改变甚至颠覆动词本义,所以必须整体记搭配;介词搭配和习语同理——错一个小词,意思就变或不地道。"],"gaokaoPoints":["语法填空/短文改错高频考''选正确小品词''与''选正确介词'';读写中能否地道用短语直接影响语言分。","易混对子:hand out vs hand in;give up vs give away;be grateful for(事)vs be grateful to(人);in need of vs in need。"],"examVsReal":[{"exam":"make a difference to sb''s life(考试规范搭配)","real":"really make a difference / make a real difference","note":"口语里常加 really 或形容词,但核心搭配不变"},{"exam":"on behalf of the whole class（正式书面）","real":"for the whole class / speaking for everyone","note":"口语常用更简单的 for…;on behalf of 多见于正式致辞"}]}'::jsonb);
